"""Golden Dragon: generated by the forge, its own identity (no link to its siblings), paths that follow the moved folders,
the fusion tool wired in, the build script, and the Golden Bird modules carried over unchanged except for the renames."""
import ast
import hashlib
import importlib.util
import json
import os
import re
import warnings
from pathlib import Path

import pytest

from conftest import APP, FORGE, GB, read, tree

PY = sorted(p.name for p in APP.glob("*.py"))


def test_generated_by_forge_and_untouched():
    stamp = json.loads(read(".gd_generated.json"))
    assert stamp["recipes"] >= 40 and stamp["fusion_counts"]["skill"] >= 500
    changed = [p for p, h in stamp["files"].items() if hashlib.sha256((APP / p).read_bytes()).hexdigest() != h]
    assert changed == [], f"edited by hand (move the change to forge): {changed}"


@pytest.mark.parametrize("name", PY)
def test_compiles_without_warnings(name):
    with warnings.catch_warnings():
        warnings.simplefilter("error")                 # an invalid escape in the prompt f-string was caught this way
        compile(read(name), name, "exec")


def test_identity_mutex_settings_port():
    app, control = read("app.py"), read("control.py")
    assert 'APP = "التنين الذهبي"' in app
    assert '"Local\\\\GoldenDragonDesktopApp"' in app
    assert '/ "GoldenDragon" / "settings.json"' in app
    assert "BRIDGE_PORT = 47851" in control
    assert "const PORT = 47851;" in read("chrome_extension/background.js")


def test_extension_is_the_v14_bridge():
    """The White Bird's hand-made v1.4 extension (watchdog, keep-alive, tab group) moved into its forge on 2026-11-15 and
    reaches the Golden Dragon with its own name and port."""
    man = json.loads(read("chrome_extension/manifest.json"))
    bg = read("chrome_extension/background.js")
    assert man["version"] == "1.4.0" and "http://127.0.0.1:47851/*" in man["host_permissions"]
    assert (APP / "chrome_extension" / "offscreen.html").is_file() and (APP / "chrome_extension" / "offscreen.js").is_file()
    assert "title: 'التنين الذهبي'" in bg and "withTimeout" in bg


def test_no_link_to_the_siblings():
    rx = re.compile(r"478[234]1|Local\\+(?:WhiteBird|BlackDragon|GoldenBird)|\.goldenbird-build|\.whitebird-build")
    for p in APP.rglob("*"):
        rel = p.relative_to(APP).as_posix()
        if p.is_file() and p.suffix in (".py", ".js", ".json", ".html", ".ps1") and rel != "fusion/lessons.json":
            assert not rx.search(p.read_text(encoding="utf-8-sig", errors="replace")), rel


def test_first_run_copies_golden_bird_first():
    app = read("app.py")
    assert 'for n in ("GoldenBird", "WhiteBird", "BlackDragon")' in app
    assert 'if src.name in ("BlackDragon", "WhiteBird", "GoldenBird"):' in app


def _gd_home():
    """The generated _home_of() (inherited from the Golden Bird forge) on its own, so its search order can be tested with a
    fake home folder."""
    fn = next(n for n in tree().body if isinstance(n, ast.FunctionDef) and n.name == "_home_of")
    ns = {"os": os, "Path": Path}
    exec(compile(ast.Module([fn], []), "app.py", "exec"), ns)
    return ns["_home_of"]


def test_paths_follow_the_moved_folders(tmp_path, monkeypatch):
    home = _gd_home()
    monkeypatch.setattr(Path, "home", staticmethod(lambda: tmp_path))
    monkeypatch.delenv("BLACK_DRAGON_HOME", raising=False)
    moved = tmp_path / "OneDrive" / "Desktop" / "مهارات" / "التنين الأسود"
    moved.mkdir(parents=True)
    assert home("BLACK_DRAGON_HOME", "التنين الأسود") == moved            # the 2026-11-15 layout
    direct = tmp_path / "OneDrive" / "Desktop" / "التنين الأسود"
    direct.mkdir(parents=True)
    assert home("BLACK_DRAGON_HOME", "التنين الأسود") == direct           # a folder on the Desktop itself wins
    monkeypatch.setenv("BLACK_DRAGON_HOME", str(tmp_path / "x"))
    assert home("BLACK_DRAGON_HOME", "التنين الأسود") == tmp_path / "x"   # the env var wins over both
    monkeypatch.delenv("BLACK_DRAGON_HOME")
    assert home("NOPE_HOME", "مش موجود") == tmp_path / "OneDrive" / "Desktop" / "مهارات" / "مش موجود"


def test_engine_repo_resolves_on_this_pc():
    app = read("app.py")
    assert 'REPO = _home_of("BLACK_DRAGON_HOME", REPO_DIRNAME)' in app
    assert 'APP_SOURCE = _home_of("GOLDEN_DRAGON_HOME", "التنين الذهبي") / "app"' in app
    assert "`fusion show program:<id>` أو `where.exe <الاسم>`" in app and 'MONTAGE / "CLAUDE.md"' not in app
    assert "OneDrive\" / \"Desktop\" / REPO_DIRNAME))" not in app                  # the stale Golden Bird line is gone
    assert "مهارات" in read("mcp_dragon.py")


def test_fusion_tool_dispatch_and_prompt():
    app = read("app.py")
    m = re.search(r'    tool\("fusion",.*?\["action"\]\)', app, re.S)
    assert m and "approval=True" not in m.group(0)                                 # read-only: no approval needed
    assert 'if name == "fusion":\n            return fusion_dispatch(a)' in app
    assert "def fusion_dispatch(a):" in app
    assert "## التنين الذهبي: الانصهار وبروتوكول الصح من أول مرة" in app and "brief أول خطوة" in app
    assert "fusion check" in app and "rd.py consent" in app and "rd.py teach" in app
    assert "dragon_fusion.py\" brief" in app                                     # subscription-mode command
    for lesson in ("AAC", "ستوري بورد", "overlay"):                               # the chosen lessons reached the prompt
        assert lesson in app
    # the experience block is its own section, right before the Red Dragon brain (not glued to the steer section)
    assert re.search(r"\n## خبرة التنين الذهبي[^\n]*\n(?:.*\n)*?\n## عقل التنين الأحمر", app)


def test_one_thinking_ladder_from_the_scholars():
    """The scholars' protocol is the ONE ladder: ① to ⑧ once, in the fusion section, with the command at each step. The
    inherited 7-rung ladder became a pointer, and multi-step work starts with fusion brief (rd think for deep work)."""
    app = read("app.py")
    sec = app.split("\n## التنين الذهبي: الانصهار", 1)[1].split("\n## ", 1)[0]
    assert re.findall(r"\n  ([①②③④⑤⑥⑦⑧]) ", sec) == list("①②③④⑤⑥⑦⑧")
    for thinker in ("بوليا", "كانيمان", "فيرمي", "هوير", "كلاين", "مانجر", "بوبر", "تيتلوك"):
        assert thinker in sec, thinker
    n = re.search(r"أدوات العلماء \((\d+)،", sec)
    assert n and int(n.group(1)) >= 20 and sec.count("«") >= int(n.group(1))
    assert "  1. فهم.\n" not in app and "هو «بروتوكول الصح من أول مرة» (① لـ ⑧)" in app
    assert "ابدأ بـ `fusion brief`. ولو العمق L2 أو L3" in app and "وفي كل الأحوال، قبل الرد: `fusion check`." in app
    assert app.count("\n## عقل العلماء") == 0                               # no second, separate ladder


def test_build_script():
    b = read("build.ps1")
    assert "--name GoldenDragon" in b and "golden-dragon.ico" in b and ".goldendragon-build" in b
    assert '--add-data "$here\\fusion;fusion"' in b and "--hidden-import dragon_fusion" in b
    assert ",".join(f"0x{ord(c):x}" for c in "التنين الذهبي") in b                 # Desktop shortcut name
    assert "run_tests.ps1" in b and "-SkipTests" in b


def test_ui_dragon_layer_and_icon():
    html = read("ui/index.html")
    assert "التنين الذهبي — dragon layer" in html and 'class="gd-badge"' in html
    assert "gb-badge\">" not in html                                                 # the old badge was replaced
    for name, src in (("ui/golden-dragon.ico", "golden-dragon.ico"), ("ui/golden-dragon.png", "gd-256.png")):
        assert (APP / name).read_bytes() == (FORGE / "overlay" / "icon" / src).read_bytes()
    assert not (APP / "ui" / "golden-bird.ico").exists()


def test_golden_modules_are_the_golden_bird_ones_renamed():
    """golden_tools / golden_steer = the Golden Bird forge modules + the identity renames only, so the Golden Bird's own 74
    tests cover their behaviour here too."""
    if not (GB / "forge" / "modules").is_dir():      # the Golden Bird forge lives only on the owner's laptop, not in the repo
        pytest.skip(f"Golden Bird forge not here: {GB}")
    spec = importlib.util.spec_from_file_location("make_golden_dragon_t", FORGE / "make_golden_dragon.py")
    forge = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(forge)
    for name in ("golden_tools.py", "golden_steer.py"):
        src = (GB / "forge" / "modules" / name).read_text(encoding="utf-8")
        assert forge.rename(src, name) == read(name), name
